// ── Auto-clasificación de intención — campañas Chile ─────────────────────
// Detecta la intención del mensaje del lead y define la transición de estado.
// La POLÍTICA de etiquetas vive aquí (edita las listas y el bloque de decisión).

// Si true, pide a tag-lead crear el lead cuando el teléfono no existe en la BD
// (en vez de perder la etiqueta). Cámbialo a false para no crear leads nuevos.
const CREAR_LEAD_SI_NO_EXISTE = true;

// Normaliza: minúsculas, sin tildes.
const norm = (s) => (s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

// Match por palabra/frase COMPLETA (evita falsos positivos de includes():
// "baja" no matchea "trabajando", "no" no matchea "nota").
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const matchAny = (texto, keywords) => {
  for (const k of keywords) {
    const kn = norm(k).trim();
    if (!kn) continue;
    const re = new RegExp("(^|[^\\p{L}\\p{N}])" + esc(kn) + "([^\\p{L}\\p{N}]|$)", "u");
    if (re.test(texto)) return k;
  }
  return null;
};

// RECHAZO — el lead NO está interesado (máxima prioridad).
const RECHAZO = [
  "no me interesa", "no me interesan", "no quiero", "no gracias",
  "no estoy interesado", "no estoy interesada", "ya no me interesa",
  "no interesa", "no quiero informacion", "no quiero saber nada",
  "no molesten", "no me molesten", "dejen de escribir", "dar de baja",
  "darme de baja", "eliminenme", "borrenme", "quitenme", "no contactar"
];

// ANTI_RECHAZO — frases que invalidan un rechazo aparente.
const ANTI_RECHAZO = ["dejar de recibir", "dejar de molestar", "perderme"];

// PROPIEDADES — el lead quiere ver opciones.
const PROPIEDADES = [
  "ver propiedades", "quiero ver", "enviame", "mandame", "envienme",
  "catalogo", "lista de propiedades", "quiero informacion",
  "que propiedades", "ver opciones", "enviar propiedades",
  "que tienen disponible", "me interesan las propiedades",
  "mas informacion", "quiero comprar", "quiero arrendar"
];

const body = ($input.first().json && $input.first().json.body) || $input.first().json || {};

// Teléfono — acepta variantes con sufijo JID de WhatsApp (@s.whatsapp.net).
const telefonoRaw = (body.telefono || body.phone || body.numero || "").toString();
const telefono = telefonoRaw.split("@")[0].replace(/\D/g, "");
if (!telefono) throw new Error("telefono requerido en el payload del webhook");

const mensaje = norm(
  body.mensaje || body.message || body.text ||
  (body.data && body.data.message && body.data.message.conversation) || ""
).trim();
const evento = (body.evento || "mensaje_recibido").toLowerCase();
const nombre = (body.nombre || body.name || "").toString();

// ── Decisión de intención y transición de estado ───────────────────────
let intent, out;
const hitRechazo = matchAny(mensaje, RECHAZO);
const antiRechazo = matchAny(mensaje, ANTI_RECHAZO);

if (hitRechazo && !antiRechazo) {
  // Señal fuerte: reemplaza TODO el estado del lead por "No interesa".
  intent = "rechazo";
  out = { tag_nombres: ["No interesa"], mode: "add", grupo_exclusivo: "estado_lead" };
} else if (matchAny(mensaje, PROPIEDADES)) {
  // Quiere propiedades: quita estados contradictorios pero respeta agente/cita.
  intent = "propiedades";
  out = {
    tag_nombres: ["Solo quiere propiedades"], mode: "add",
    remove_tag_nombres: ["No interesa", "Pendiente asignar agente"]
  };
} else {
  // Respondió algo (incl. media/vacío): marcar para agente SOLO si aún no
  // tiene un estado asignado (no pisa "Cita agendada", "Agente asignado", etc.).
  intent = "respuesta_generica";
  out = {
    tag_nombres: ["Pendiente asignar agente"], mode: "add",
    grupo_exclusivo: "estado_lead", solo_si_grupo_vacio: true
  };
}

return [{
  json: {
    telefono,
    nombre,
    crear_si_no_existe: CREAR_LEAD_SI_NO_EXISTE,
    ...out,
    _debug: { mensaje_original: body.mensaje || "", intent, evento }
  }
}];

// Log de resultado — append-only (nunca borra)
const resultado = $input.first().json;
const debug = $('Clasificar intención').first().json._debug || {};

console.log(JSON.stringify({
  ts: new Date().toISOString(),
  telefono: $('Clasificar intención').first().json.telefono,
  intent: debug.intent,
  tag_ids: resultado.tag_ids,
  success: resultado.success,
  warning: resultado.warning || null
}));

return [{ json: { ok: true, ...resultado } }];
